func (s *Service) notifyNewPayload(ctx context.Context, preStateVersion int,
    preStateHeader interfaces.ExecutionData, blk interfaces.ReadOnlySignedBeaconBlock) (bool, error) {
    ctx, span := trace.StartSpan(ctx, "blockChain.notifyNewPayload")
    defer span.End()

    if blk == nil {
        return false, errors.New("signed beacon block can't be nil")
    }
    if preStateVersion < version.Bellatrix {
        return true, nil
    }
    if err := consensusblocks.BeaconBlockIsNil(blk); err != nil {
        return false, err
    }
    body := blk.Block().Body()
    enabled, err := blocks.IsExecutionEnabledUsingHeader(preStateHeader, body)
    if err != nil {
        return false, errors.Wrap(invalidBlock{error: err}, "could not determine if execution is enabled")
    }
    if !enabled {
        return true, nil
    }
    payload, err := body.Execution()
    if err != nil {
        return false, errors.Wrap(invalidBlock{error: err}, "could not get execution payload")
    }

    var lastValidHash []byte
    var parentRoot *common.Hash
    var versionedHashes []common.Hash
    var requests *enginev1.ExecutionRequests
    if blk.Version() >= version.Deneb {
        versionedHashes, err = kzgCommitmentsToVersionedHashes(blk.Block().Body())
        if err != nil {
            return false, errors.Wrap(err, "could not get versioned hashes to feed the engine")
        }
        prh := common.Hash(blk.Block().ParentRoot())
        parentRoot = &prh
    }
    if blk.Version() >= version.Electra {
        requests, err = blk.Block().Body().ExecutionRequests()
        if err != nil {
            return false, errors.Wrap(err, "could not get execution requests")
        }
        if requests == nil {
            return false, errors.New("nil execution requests")
        }
    }
    lastValidHash, err = s.cfg.ExecutionEngineCaller.NewPayload(ctx, payload, versionedHashes, parentRoot, requests)
    // ... error handling
}
```

KEY OBSERVATIONS ON OMMERS VALIDATION:
- The `notifyNewPayload` function passes the execution payload to the EL via `NewPayload`
- There is NO explicit ommers/uncle hash validation in Prysm's beacon chain code
- The beacon chain uses SSZ-encoded execution payloads (ExecutionPayload protobuf) which do NOT have an ommers/uncle field - ommers are an EL-level concept in legacy Ethereum
- In post-merge (Bellatrix+), the beacon chain passes `ExecutionPayload` to the EL via engine_newPayloadV1/V2/V3/V4 - the EL is responsible for validating that the ommer hash equals keccak256(RLP([])) (empty uncle list hash)
- Prysm delegates this validation entirely to the execution layer client (go-ethereum, etc.)
- The `validateDataColumn` function is unrelated to ommer validation

